/**
 * Code node · "Validate & Normalize" (run once for all items)
 * In : Webhook item — body is a pp.quote.v1 payload from the quote configurator
 * Out: one item { valid, spam, httpStatus, errors[], config, lead{}, row{} }
 *
 * Nothing downstream re-reads the raw webhook body: this node is the only place
 * that trusts client input, and every field is length-capped and type-checked.
 */

const CONFIG = {
  // 'pilot' → every INTERNAL email goes to pilotRecipient (buyer emails always go to the buyer).
  // Switch to 'live' once Pure Polymers signs off on the routing addresses.
  mode: 'pilot',
  pilotRecipient: 'oussama.g@oussamalabs.com',
  replyTo: 'info@purepolymers.net',
  whatsappE164: '966546460891',
  visualizerUrl: 'https://colorsvisualizer.com/',
  quoteLogUrl: 'https://docs.google.com/spreadsheets/d/1DUd4fQiYWlL86c7_Io0GjQ2oM6u8vcK99Bkw9xXs3ks/edit',
  slaBusinessHours: 18, // 2 business days on a 9 h desk
  desk: { utcOffsetHours: 3, workDays: [0, 1, 2, 3, 4], openHour: 8, closeHour: 17 },
}

const ROUTE_TEAM = {
  color_pigment: 'Color Lab',
  additive: 'Additives Technical Desk',
  compound: 'Compounding Team',
  unclassified: 'Sales Desk (triage)',
}
const FAMILY_ROUTE = { CM: 'color_pigment', WM: 'color_pigment', BM: 'color_pigment', AM: 'additive', PC: 'compound' }
const VOLUME_SCORE = { lt5: 5, '5-25': 15, '25-100': 30, '100-500': 40, gt500: 45, unknown: 8 }
const TIMELINE_SCORE = { urgent: 25, month: 18, quarter: 10, planning: 4 }
const FREE_MAIL = ['gmail.com', 'hotmail.com', 'outlook.com', 'yahoo.com', 'icloud.com', 'live.com']
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/

const first = $input.first().json
const b = first && typeof first.body === 'object' && first.body !== null ? first.body : first
const errors = []

const s = (value, max) => String(value === undefined || value === null ? '' : value).replace(/[\t\r\n]+/g, ' ').trim().slice(0, max || 300)
const lines = (value, max) => String(value === undefined || value === null ? '' : value).replace(/\r/g, '').trim().slice(0, max || 1500)
const labelOf = (option) => (option && typeof option === 'object' ? s(option.label, 80) : '')
const yesNo = (value) => (value ? 'Yes' : 'No')

if (s(b && b.schema, 20) !== 'pp.quote.v1') errors.push('unsupported schema')

const submissionId = s(b && b.submissionId, 64)
if (!/^[0-9a-fA-F-]{16,64}$/.test(submissionId)) errors.push('submissionId missing or malformed')

const reference = s(b && b.reference, 20).toUpperCase()
if (!/^PP-\d{4}-[A-Z]{2}$/.test(reference)) errors.push('reference malformed')

const familyCode = s(b && b.family && b.family.code, 2).toUpperCase()
const route = FAMILY_ROUTE[familyCode] || 'unclassified'

const products = (Array.isArray(b && b.products) ? b.products : [])
  .slice(0, 5)
  .map((p) => ({
    id: s(p && p.id, 40),
    name: s(p && p.name, 80),
    family: s(p && p.family, 20),
    tds: s(p && p.tds, 40),
    specs: (Array.isArray(p && p.specsReadable) ? p.specsReadable : [])
      .slice(0, 14)
      .map((r) => ({ label: s(r && r.label, 80), value: s(r && r.value, 200) }))
      .filter((r) => r.label && r.value),
  }))
  .filter((p) => p.id && p.name)
if (!products.length) errors.push('at least one product is required')

const contact = (b && b.contact) || {}
const email = s(contact.email, 160).toLowerCase()
if (!EMAIL_RE.test(email)) errors.push('valid email is required')
if (!s(contact.firstName, 60)) errors.push('first name is required')
if (!s(contact.company, 100)) errors.push('company is required')
if (!(b && b.consent && b.consent.contact === true)) errors.push('contact consent is required')

// Honeypot: real buyers never see this field.
const spam = s(b && b.hp, 200) !== ''

const application = (b && b.application) || {}
const commercial = (b && b.commercial) || {}
const delivery = commercial.delivery || {}
const source = (b && b.source) || {}

const volumeId = s(commercial.annualVolume && commercial.annualVolume.id, 20)
const timelineId = s(commercial.timeline && commercial.timeline.id, 20)
const phone = s(contact.phone, 40)
const phoneDigits = phone.replace(/\D/g, '')
const domain = email.split('@')[1] || ''
const businessEmail = Boolean(domain) && FREE_MAIL.indexOf(domain) === -1

let score = (VOLUME_SCORE[volumeId] || 0) + (TIMELINE_SCORE[timelineId] || 0)
if (businessEmail) score += 10
if (phoneDigits.length >= 9 && contact.whatsappOptIn === true) score += 5
if (products.some((p) => p.specs.length >= 2)) score += 5
if (s(commercial.targetPrice, 60) || s(commercial.benchmark, 80)) score += 5
if (score > 100) score = 100
const tier = score >= 65 ? 'HOT' : score >= 40 ? 'WARM' : 'NURTURE'

/* Saudi desk calendar: Sunday–Thursday, 08:00–17:00, Asia/Riyadh = UTC+3 year-round. */
const OFFSET_MS = CONFIG.desk.utcOffsetHours * 3600000
const DAY_MS = 86400000
function parts(date) {
  const d = new Date(date.getTime() + OFFSET_MS)
  return { y: d.getUTCFullYear(), m: d.getUTCMonth(), day: d.getUTCDate(), dow: d.getUTCDay(), minutes: d.getUTCHours() * 60 + d.getUTCMinutes() }
}
function at(y, m, day, hour) {
  return new Date(Date.UTC(y, m, day, hour, 0) - OFFSET_MS)
}
function nextOpening(after) {
  for (let i = 0; i <= 7; i++) {
    const p = parts(new Date(after.getTime() + i * DAY_MS))
    const opening = at(p.y, p.m, p.day, CONFIG.desk.openHour)
    if (CONFIG.desk.workDays.indexOf(p.dow) !== -1 && opening.getTime() > after.getTime()) return opening
  }
  return new Date(after.getTime() + DAY_MS)
}
function addBusinessHours(start, hours) {
  let remaining = hours * 60
  let cursor = new Date(start)
  for (let guard = 0; guard < 64; guard++) {
    const p = parts(cursor)
    if (CONFIG.desk.workDays.indexOf(p.dow) === -1 || p.minutes >= CONFIG.desk.closeHour * 60) {
      cursor = nextOpening(cursor)
      continue
    }
    if (p.minutes < CONFIG.desk.openHour * 60) {
      cursor = at(p.y, p.m, p.day, CONFIG.desk.openHour)
      continue
    }
    const available = CONFIG.desk.closeHour * 60 - p.minutes
    if (remaining <= available) return new Date(cursor.getTime() + remaining * 60000)
    remaining -= available
    cursor = nextOpening(at(p.y, p.m, p.day, CONFIG.desk.closeHour))
  }
  return cursor
}
const fmt = (date) =>
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Riyadh',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date) + ' AST'

const receivedAt = new Date()
const slaDue = addBusinessHours(receivedAt, CONFIG.slaBusinessHours)

const polymers = (Array.isArray(application.polymers) ? application.polymers : []).map(labelOf).filter(Boolean).join(', ')
const specsText = products
  .map((p) => p.name + ': ' + (p.specs.map((r) => r.label + ' = ' + r.value).join('; ') || 'no specification given'))
  .join(' | ')
const utm = source.utm && typeof source.utm === 'object'
  ? Object.keys(source.utm).slice(0, 6).map((k) => s(k, 20) + '=' + s(source.utm[k], 60)).join('&')
  : ''

const lead = {
  reference,
  submissionId,
  familyCode,
  route,
  team: ROUTE_TEAM[route],
  tier,
  score,
  receivedAtIso: receivedAt.toISOString(),
  receivedAtLocal: fmt(receivedAt),
  slaDueIso: slaDue.toISOString(),
  slaDueLocal: fmt(slaDue),
  contact: {
    firstName: s(contact.firstName, 60),
    lastName: s(contact.lastName, 60),
    fullName: (s(contact.firstName, 60) + ' ' + s(contact.lastName, 60)).trim(),
    email,
    phone,
    phoneDigits,
    whatsapp: contact.whatsappOptIn === true,
    company: s(contact.company, 100),
    role: labelOf(contact.role),
    channel: s(contact.preferredChannel, 20) || 'email',
    language: contact.language === 'ar' ? 'ar' : 'en',
    businessEmail,
  },
  products,
  application: {
    polymers,
    process: labelOf(application.process),
    market: labelOf(application.market),
    finalProduct: s(application.finalProduct, 160),
  },
  commercial: {
    annualVolume: labelOf(commercial.annualVolume),
    annualVolumeId: volumeId,
    firstOrder: labelOf(commercial.firstOrder),
    timeline: labelOf(commercial.timeline),
    timelineId,
    sampleRequested: commercial.sampleRequested === true,
    country: s(delivery.country, 60),
    city: s(delivery.city, 80),
    incoterm: s(delivery.incoterm, 40),
    targetPrice: s(commercial.targetPrice, 60),
    benchmark: s(commercial.benchmark, 80),
  },
  notes: lines(b && b.notes, 1500),
  source: {
    page: s(source.page, 300),
    referrer: s(source.referrer, 300),
    utm,
    prefilledBy: s(source.prefilledBy, 20),
    locale: s(source.locale, 20),
  },
}

const row = {
  received_at: lead.receivedAtIso,
  reference: lead.reference,
  status: 'New',
  tier: lead.tier,
  score: lead.score,
  route: lead.route,
  team: lead.team,
  sla_due_at: lead.slaDueIso,
  company: lead.contact.company,
  contact_name: lead.contact.fullName,
  role: lead.contact.role,
  email: lead.contact.email,
  phone: lead.contact.phone,
  whatsapp: yesNo(lead.contact.whatsapp),
  preferred_channel: lead.contact.channel,
  language: lead.contact.language,
  products: products.map((p) => p.name).join(' + '),
  product_ids: products.map((p) => p.id).join(','),
  specs: specsText,
  polymers: lead.application.polymers,
  process: lead.application.process,
  market: lead.application.market,
  final_product: lead.application.finalProduct,
  annual_volume: lead.commercial.annualVolume,
  first_order: lead.commercial.firstOrder,
  timeline: lead.commercial.timeline,
  sample: yesNo(lead.commercial.sampleRequested),
  delivery_country: lead.commercial.country,
  delivery_city: lead.commercial.city,
  incoterm: lead.commercial.incoterm,
  target_price: lead.commercial.targetPrice,
  benchmark: lead.commercial.benchmark,
  notes: lead.notes,
  source_page: lead.source.page,
  utm: lead.source.utm,
  prefilled_by: lead.source.prefilledBy,
  submission_id: lead.submissionId,
}

return [
  {
    json: {
      valid: errors.length === 0 && !spam,
      spam,
      // Spam gets a 200 so bots learn nothing; real validation problems get 422.
      httpStatus: spam ? 200 : errors.length ? 422 : 200,
      errors,
      config: CONFIG,
      lead,
      row,
    },
  },
]

/**
 * Code node · "Compose Sales Alert" (run once for all items)
 * In : the executed route Set node (Switch branch)
 * Out: one item { to, cc, subject, html } for the internal Gmail node
 */

const BRAND = {
  ink: '#0B0F14',
  ink2: '#151b23',
  paper: '#F5F7FA',
  line: '#dfe4ea',
  text: '#1d242e',
  muted: '#5d6875',
  green: '#509C35',
  lime: '#BECC30',
  blue: '#3249B3',
  amber: '#E09A2D',
  whatsapp: '#1ea952',
}

function esc(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function row(label, value) {
  if (!value) return ''
  return (
    '<tr>' +
    '<td style="padding:6px 12px 6px 0;font:12px Arial,sans-serif;color:' + BRAND.muted + ';white-space:nowrap;vertical-align:top;">' + esc(label) + '</td>' +
    '<td style="padding:6px 0;font:13px Arial,sans-serif;color:' + BRAND.text + ';vertical-align:top;">' + esc(value) + '</td>' +
    '</tr>'
  )
}

function table(rows) {
  const body = rows.filter(Boolean).join('')
  return body ? '<table role="presentation" cellpadding="0" cellspacing="0" width="100%">' + body + '</table>' : ''
}

function sectionTitle(text) {
  return '<p style="margin:22px 0 8px;font:600 10px/1.4 Consolas,Menlo,monospace;letter-spacing:2px;text-transform:uppercase;color:' + BRAND.muted + ';">' + esc(text) + '</p>'
}

function button(href, label, background, color) {
  return (
    '<a href="' + esc(href) + '" style="display:inline-block;background:' + background + ';color:' + (color || '#ffffff') +
    ';font:600 14px Arial,sans-serif;text-decoration:none;padding:12px 22px;border-radius:8px;">' + esc(label) + '</a>'
  )
}

function preheader(text) {
  return '<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:' + BRAND.paper + ';">' + esc(text) + '</div>'
}

/** 600px branded shell used by every outbound email. */
function shell(options) {
  return (
    '<div style="background:' + BRAND.paper + ';padding:24px 12px;">' +
    preheader(options.preheader || '') +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border:1px solid ' + BRAND.line + ';border-radius:14px;overflow:hidden;">' +
    '<tr><td style="background:' + BRAND.ink + ';padding:18px 26px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
    '<td style="font:700 18px Arial,sans-serif;color:#ffffff;">Pure Polymers' +
    '<div style="font:italic 600 11px Arial,sans-serif;color:' + BRAND.lime + ';padding-top:3px;">Real Passion for Quality</div></td>' +
    '<td align="right" style="font:600 11px Consolas,Menlo,monospace;color:' + BRAND.lime + ';letter-spacing:1px;">' + esc(options.badge || '') + '</td>' +
    '</tr></table></td></tr>' +
    '<tr><td style="height:4px;background:linear-gradient(90deg,' + BRAND.green + ',' + BRAND.lime + ',' + BRAND.blue + ');font-size:0;line-height:0;">&nbsp;</td></tr>' +
    '<tr><td style="padding:26px;">' + options.body + '</td></tr>' +
    '<tr><td style="background:#f2f4f7;padding:16px 26px;font:12px Arial,sans-serif;color:' + BRAND.muted + ';">' + options.footer + '</td></tr>' +
    '</table></div>'
  )
}

function waLink(phoneDigits, text) {
  return 'https://wa.me/' + phoneDigits + (text ? '?text=' + encodeURIComponent(text) : '')
}


const v = $('Validate & Normalize').first().json
const lead = v.lead
const config = v.config

// Exactly one Switch branch runs per execution; find which route Set node fired.
const ROUTE_NODES = ['Route · Color Lab', 'Route · Additives Desk', 'Route · Compounding Team', 'Route · Sales Triage']
let route = null
for (const name of ROUTE_NODES) {
  try {
    if ($(name).isExecuted) {
      route = $(name).first().json
      break
    }
  } catch (error) {
    // node not part of this execution path
  }
}
if (!route) route = { route_team: lead.team, route_recipients: config.pilotRecipient, route_variant: 'triage', route_focus: '' }

const tierStyle = { HOT: { emoji: '🔥', color: '#c2410c' }, WARM: { emoji: '🟡', color: '#a16207' }, NURTURE: { emoji: '⚪', color: BRAND.muted } }[lead.tier]
const productNames = lead.products.map((p) => p.name).join(' + ')

const replyBody =
  'Dear ' + lead.contact.firstName + ',%0D%0A%0D%0AThank you for your request ' + lead.reference + '.%0D%0A%0D%0A'
const mailto =
  'mailto:' + lead.contact.email +
  '?subject=' + encodeURIComponent('Pure Polymers quotation ' + lead.reference + ' — ' + productNames) +
  '&body=' + replyBody
const waText =
  'Hello ' + lead.contact.firstName + ', this is Pure Polymers (Modon 3, Jeddah) about your quote request ' +
  lead.reference + ' for ' + productNames + '.'

const specBlocks = lead.products
  .map(
    (p) =>
      '<div style="border:1px solid ' + BRAND.line + ';border-radius:10px;padding:12px 14px;margin-bottom:10px;">' +
      '<div style="font:600 14px Arial,sans-serif;color:' + BRAND.text + ';">' + esc(p.name) + '</div>' +
      table(p.specs.map((r) => row(r.label, r.value))) +
      '</div>',
  )
  .join('')

const body =
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
  '<td style="font:700 22px Arial,sans-serif;color:' + BRAND.text + ';">' + tierStyle.emoji + ' ' + esc(lead.tier) +
  ' lead · <span style="font-family:Consolas,Menlo,monospace;">' + esc(lead.reference) + '</span></td>' +
  '<td align="right" style="font:600 12px Arial,sans-serif;color:' + tierStyle.color + ';">score ' + lead.score + '/100</td>' +
  '</tr></table>' +
  '<p style="margin:6px 0 0;font:13px Arial,sans-serif;color:' + BRAND.muted + ';">' +
  esc(route.route_team) + ' · received ' + esc(lead.receivedAtLocal) +
  ' · <strong style="color:' + BRAND.text + ';">quotation due ' + esc(lead.slaDueLocal) + '</strong></p>' +
  (route.route_focus
    ? '<p style="margin:14px 0 0;padding:10px 12px;background:#f2f7ef;border-left:3px solid ' + BRAND.green +
      ';font:13px Arial,sans-serif;color:' + BRAND.text + ';">' + esc(route.route_focus) + '</p>'
    : '') +
  sectionTitle('Buyer') +
  table([
    row('Company', lead.contact.company),
    row('Contact', lead.contact.fullName + (lead.contact.role ? ' · ' + lead.contact.role : '')),
    row('Email', lead.contact.email),
    row('Phone', lead.contact.phone + (lead.contact.whatsapp ? ' (WhatsApp)' : '')),
    row('Prefers', lead.contact.channel + ' · replies in ' + (lead.contact.language === 'ar' ? 'Arabic' : 'English')),
    row('Email type', lead.contact.businessEmail ? 'Company domain' : 'Free mailbox'),
  ]) +
  sectionTitle('Technical request') +
  specBlocks +
  table([
    row('Base polymer', lead.application.polymers),
    row('Process', lead.application.process),
    row('End market', lead.application.market),
    row('Final product', lead.application.finalProduct),
  ]) +
  sectionTitle('Commercial') +
  table([
    row('Annual volume', lead.commercial.annualVolume),
    row('First order', lead.commercial.firstOrder),
    row('Timeline', lead.commercial.timeline),
    row('Lab sample first', lead.commercial.sampleRequested ? 'Yes — ships within 7 business days' : 'No'),
    row('Delivery', [lead.commercial.city, lead.commercial.country].filter(Boolean).join(', ')),
    row('Incoterm', lead.commercial.incoterm),
    row('Target price', lead.commercial.targetPrice),
    row('Grade used today', lead.commercial.benchmark),
  ]) +
  (lead.notes
    ? sectionTitle('Notes from the buyer') +
      '<p style="margin:0;font:13px/1.6 Arial,sans-serif;color:' + BRAND.text + ';white-space:pre-line;">' + esc(lead.notes) + '</p>'
    : '') +
  '<div style="margin:24px 0 6px;">' +
  button(mailto, 'Reply by email', BRAND.green) + '&nbsp;&nbsp;' +
  (lead.contact.phoneDigits ? button(waLink(lead.contact.phoneDigits, waText), 'WhatsApp the buyer', BRAND.whatsapp) + '&nbsp;&nbsp;' : '') +
  button(config.quoteLogUrl, 'Open quote log', BRAND.ink) +
  '</div>' +
  sectionTitle('Source') +
  table([
    row('Page', lead.source.page),
    row('Campaign', lead.source.utm),
    row('Prefilled by', lead.source.prefilledBy === 'assistant' ? 'AI assistant conversation' : ''),
    row('Submission id', lead.submissionId),
  ])

const html = shell({
  badge: 'NEW QUOTE REQUEST',
  preheader: lead.tier + ' · ' + productNames + ' · ' + (lead.commercial.annualVolume || 'volume not given') + ' · ' + lead.contact.company,
  body,
  footer: 'Automated by the Pure Polymers quote pipeline · reply directly to the buyer, then set the row status in the quote log.',
})

return [
  {
    json: {
      to: config.mode === 'live' ? route.route_recipients : config.pilotRecipient,
      cc: config.mode === 'live' ? route.route_cc || '' : '',
      subject:
        tierStyle.emoji + ' ' + lead.tier + ' · ' + lead.reference + ' · ' + productNames + ' · ' +
        (lead.commercial.annualVolume || 'volume TBC') + ' · ' + lead.contact.company,
      html,
      tier: lead.tier,
      reference: lead.reference,
      pingText:
        lead.tier + ' quote request ' + lead.reference + ': ' + productNames + ' for ' + lead.contact.company +
        ' (' + (lead.commercial.annualVolume || 'volume TBC') + '). Quotation due ' + lead.slaDueLocal + '.',
    },
  },
]

/**
 * Code node · "Resolve TDS Files" (run once for all items)
 * In : rows of the TDS_Library sheet tab (may be empty, or one error item)
 * Out: exactly one item { hasTds, tdsFiles[], missing[] } — never zero items, so the
 *      buyer confirmation always goes out even when no data sheet is on file.
 */

const v = $('Validate & Normalize').first().json
const rows = $input
  .all()
  .map((item) => item.json)
  .filter((r) => r && r.product_id && r.tds_file_id)

const byProduct = {}
for (const r of rows) {
  byProduct[String(r.product_id).trim()] = r
}

const tdsFiles = []
const missing = []
for (const product of v.lead.products) {
  const match = byProduct[product.id]
  if (match) {
    tdsFiles.push({
      productId: product.id,
      productName: product.name,
      fileId: String(match.tds_file_id).trim(),
      fileName: String(match.tds_file_name || 'TDS - ' + product.name + '.pdf').trim(),
      version: String(match.version || '').trim(),
    })
  } else {
    missing.push(product.name)
  }
}

return [{ json: { hasTds: tdsFiles.length > 0, tdsFiles, missing } }]
